<?php foreach(App\Models\MemberProfile::whereRaw('city REGEXP ''^[0-9]+$''')->get() as $p) { if ($city = App\Models\City::find($p->city)) { $p->city = $city->name; $p->save(); echo 'Updated ' . $p->id . PHP_EOL; } } foreach(App\Models\MemberProfile::whereRaw('state REGEXP ''^[0-9]+$''')->get() as $p) { if ($state = App\Models\State::find($p->state)) { $p->state = $state->name; $p->save(); echo 'Updated ' . $p->id . PHP_EOL; } }
